cd /home/sfmqrb/git/rishe/data/verification/sources/refs
python3 - <<'EOF'
txt=open('SYN.txt',encoding='utf-8',errors='replace').read()
pages=txt.split('\f')
import re
for i,p in enumerate(pages):
    if re.search(r'11\.8[0-9]\s+BUY|BUY\b', p) and 'sell' in p.lower():
        print('leaf',i, p[:200].replace('\n',' '))
print('---night---')
for i,p in enumerate(pages):
    if re.search(r'14\.4[0-9]\s+NIGHT|\bNIGHT\b', p) and ('nox' in p or 'xšap' in p or 'naktos' in p):
        print('leaf',i, p[:200].replace('\n',' '))
EOF

